/*
 * Only the SHAPE leaves the plan: kind, title, duration (live), library item (homework,
 * if it still exists) and a day offset. A step's day is its session time, due date or send
 * date in the coach's zone (Europe/Paris), counted from the plan's start; a step with no
 * date takes the day of the step before it. Briefs, summaries, links, hand-ins and dates
 * stay with the learner.
 */
(async () => {
  const refuse = (why) => { Outputs.why = why; Outputs.refuse(); };
  try {
    const R = Noodl.Records;
    const q = (c, where) => R.query(c, where, { limit: 1000, plain: true });
    const planId = String(Inputs.planId || '');
    const plans = planId ? await q('Plan', { objectId: { equalTo: planId } }) : [];
    if (plans.length !== 1) return refuse('That plan is no longer there. Reload the page.');
    const title = String(Inputs.title || '').trim().replace(/\s+/g, ' ');
    if (!title) return refuse('Give the template a title.');
    if (title.length > 140) return refuse('Keep the title under 140 characters.');
    const description = String(Inputs.description || '').trim();
    if (description.length > 2000) return refuse('Keep the description under 2,000 characters.');
    const steps = (await q('Step', { plan: { equalTo: planId } })).sort((a, b) => a.position - b.position);
    if (!steps.length) return refuse('This plan has no steps yet, so there is nothing to save.');

    const parisDay = (iso) => new Date(iso).toLocaleDateString('en-CA', { timeZone: 'Europe/Paris' });
    const dayNumber = (ymd) => { const [y, m, d] = ymd.split('-').map(Number); return Date.UTC(y, m - 1, d) / 86400000; };
    const dated = steps.map((s) => s.startsAt || s.dueAt || s.sendsAt).filter(Boolean).map(parisDay).sort();
    const start = plans[0].startedOn || dated[0];
    const libIds = steps.map((s) => s.fromLibraryItem).filter(Boolean);
    const library = libIds.length ? await q('LibraryItem', { objectId: { containedIn: libIds } }) : [];

    let previous = 0;
    const items = steps.map((s) => {
      const when = s.startsAt || s.dueAt || s.sendsAt;
      const day = when && start ? Math.max(0, dayNumber(parisDay(when)) - dayNumber(start)) : previous;
      previous = day;
      const item = { kind: s.kind, title: s.title || '', dayOffset: day };
      if (s.kind === 'live') item.durationMin = Number.isInteger(s.durationMin) ? s.durationMin : 60;
      if (s.kind === 'homework' && library.some((l) => l.objectId === s.fromLibraryItem)) item.libraryItem = s.fromLibraryItem;
      return item;
    });
    const row = await R.create('PlanTemplate', { title, description, items, archived: false }, { plain: true });
    Outputs.id = row.objectId || row.id;
    Outputs.count = items.length;
    Outputs.done();
  } catch (e) {
    console.error('[dbu:templateFromPlan]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
